<script setup>
import { computed, ref, watch } from 'vue'
import { movePlaylistLesson } from './model'
const props = defineProps({ playlists: Array, lessons: Array, pendingLesson: Object })
const emit = defineEmits(['update:playlists','open','clear-pending'])
const selectedId = ref(props.playlists[0]?.id || ''), editor = ref(''), title = ref(''), feedback = ref('')
const selected = computed(() => props.playlists.find(p => p.id === selectedId.value))
const rows = computed(() => (selected.value?.lessonIds || []).map(id => props.lessons.find(l => l.id === id)).filter(Boolean))
watch(() => props.pendingLesson, lesson => { if (lesson) feedback.value = '选择一个列表，将课时加入；也可以先创建新列表。' }, {immediate:true})
function save() {
  const text = title.value.trim()
  if (!text) { feedback.value = '请填写学习列表标题。'; return }
  if (editor.value === 'create') { const item = {id:`playlist-${Date.now()}-${Math.random().toString(36).slice(2,7)}`,title:text,lessonIds:[]}; emit('update:playlists',[...props.playlists,item]);selectedId.value=item.id }
  else emit('update:playlists',props.playlists.map(p => p.id===selectedId.value?{...p,title:text}:p))
  editor.value='';feedback.value='学习列表已保存在当前浏览器。'
}
function updateIds(ids) { emit('update:playlists',props.playlists.map(p => p.id===selectedId.value?{...p,lessonIds:ids}:p)) }
function add(lesson) { if (!selected.value) return; if (selected.value.lessonIds.includes(lesson.id)) {feedback.value='这个课时已经在列表里。';return} updateIds([...selected.value.lessonIds,lesson.id]);feedback.value=`已添加：${lesson.title}`;emit('clear-pending') }
function move(id, delta) { const ids=selected.value.lessonIds; updateIds(movePlaylistLesson(ids,ids.indexOf(id),delta)) }
</script>
<template>
  <div class="playlist-heading"><div><p class="overline">YOUR LEARNING PLAYLISTS</p><h1>把好内容，排进你的计划。</h1><p>按自己的节奏整理课时。列表与顺序仅保存在当前浏览器。</p></div><button class="primary" @click="editor='create';title='';feedback=''">＋ 新建学习列表</button></div>
  <section v-if="pendingLesson" class="pending"><div><strong>待加入：{{ pendingLesson.title }}</strong><p>请选择下方学习列表，再点击「加入此列表」。</p></div><button class="secondary" @click="emit('clear-pending')">取消</button></section>
  <p v-if="feedback" class="feedback" role="status">{{ feedback }}</p>
  <div class="playlist-layout"><aside class="playlist-tabs"><button v-for="playlist in playlists" :key="playlist.id" :class="{active:selectedId===playlist.id}" @click="selectedId=playlist.id;feedback=''">☷ <span>{{ playlist.title }}<small>{{ playlist.lessonIds.length }} 个课时</small></span></button><p v-if="!playlists.length">创建第一个学习列表，给好奇心安排一个顺序。</p></aside>
  <section v-if="selected" class="playlist-content"><div class="playlist-title"><div><h2>{{ selected.title }}</h2><p>{{ rows.length }} 个可用课时</p></div><button class="secondary" @click="editor='rename';title=selected.title">重命名</button></div><button v-if="pendingLesson" class="primary add-pending" @click="add(pendingLesson)">＋ 加入此列表</button><div v-if="!rows.length" class="empty"><span>☷</span><h3>你的下一课，从这里开始。</h3><p>从合集详情的「加入列表」添加内容，或从下方直接选择。</p></div><article v-for="(lesson,index) in rows" :key="lesson.id" class="playlist-lesson"><span class="position">{{ String(index+1).padStart(2,'0') }}</span><button class="lesson-open" @click="emit('open',lesson)"><strong>{{ lesson.title }}</strong><small>{{ lesson.level }} · {{ lesson.minutes }} 分钟 · 点击阅读</small></button><div class="row-actions"><button :disabled="index===0" :aria-label="'上移 '+lesson.title" @click="move(lesson.id,-1)">↑</button><button :disabled="index===rows.length-1" :aria-label="'下移 '+lesson.title" @click="move(lesson.id,1)">↓</button><button :aria-label="'移除 '+lesson.title" @click="updateIds(selected.lessonIds.filter(id=>id!==lesson.id))">移除</button></div></article><details class="add-lessons"><summary>＋ 从课程库添加课时</summary><div v-for="lesson in lessons" :key="lesson.id"><span>{{ lesson.title }}</span><button class="secondary" :disabled="selected.lessonIds.includes(lesson.id)" @click="add(lesson)">{{ selected.lessonIds.includes(lesson.id)?'已添加':'添加' }}</button></div></details><div class="audio-placeholder"><button disabled aria-label="上一首">◀</button><button disabled aria-label="播放">▶</button><button disabled aria-label="下一首">▶|</button><span>暂无源音频 · 当前列表用于整理阅读课时</span></div></section><section v-else class="empty welcome"><span>☷</span><h2>给内容一个自己的顺序。</h2><p>新建学习列表，把不同课程中的材料整理在一起。</p></section></div>
  <div v-if="editor" class="modal-shade" @click.self="editor=''"><section class="playlist-modal" role="dialog" aria-modal="true" aria-labelledby="playlist-dialog-title" @keydown.esc="editor=''"><button class="close" aria-label="关闭编辑" @click="editor=''">×</button><p class="overline">MAKE IT YOUR OWN</p><h2 id="playlist-dialog-title">{{ editor==='create'?'新建学习列表':'重命名列表' }}</h2><form @submit.prevent="save"><label for="playlist-title">列表标题</label><input id="playlist-title" v-model="title" maxlength="100" placeholder="例如：My morning reading" required autofocus><p v-if="feedback" class="feedback" role="alert">{{ feedback }}</p><button class="primary" type="submit">{{ editor==='create'?'创建列表':'保存名称' }}</button></form></section></div>
</template>
<style scoped>
