a,serif}.lesson-open{flex:1;border:0;background:none;color:#30425b;text-align:left;cursor:pointer;font:inherit}.lesson-open strong{font-size:13px;line-height:1.6;display:block}.lesson-open small{display:block;font-size:10px;color:#89967f;margin-top:8px}.row-actions{display:flex;gap:5px}.row-actions button{border:1px solid #e1e6da;background:#fafcf8;border-radius:5px;padding:6px 8px;cursor:pointer;color:#738262;font-size:10px}.empty{text-align:center;color:#8c9882;padding:50px 25px;line-height:1.8}.empty>span{font:60px Georgia,serif;color:#a9b795;display:block;margin-bottom:20px}.empty h3,.empty h2{color:#647853;font-size:20px}.empty p{font-size:12px;line-height:1.9;margin-top:15px}.welcome{border:1px dashed #dae2d0;border-radius:12px}.add-lessons{padding:20px 25px;font-size:12px;color:#687b52}.add-lessons summary{cursor:pointer}.add-lessons>div{display:flex;align-items:center;justify-content:space-between;gap:15px;padding:15px 0;border-bottom:1px solid #f0f2ec}.add-lessons>div span{font-size:11px;line-height:1.6}.add-lessons .secondary{font-size:10px;padding:8px 12px}.add-pending{margin:20px 25px 0;background:#baf56b;color:#40592e}.audio-placeholder{display:flex;align-items:center;justify-content:center;gap:13px;background:#f6f8f3;padding:20px;flex-wrap:wrap}.audio-placeholder button{border:0;background:#e9eee2;padding:8px 12px;border-radius:6px;color:#8e9c81}.audio-placeholder span{font-size:10px;color:#99a18d}.modal-shade{position:fixed;inset:0;background:#15233d66;z-index:100;display:grid;place-items:center;padding:25px}.playlist-modal{max-width:460px;width:100%;padding:35px;background:#fff;border-radius:14px;position:relative;box-shadow:0 20px 80px #14234033}.playlist-modal h2{font-size:25px}.playlist-modal label{display:block;font-size:12px;color:#738362;margin:25px 0 10px}.playlist-modal input{width:100%;padding:13px;border:1px solid #d5dfc8;border-radius:7px;font:inherit;font-size:13px}.playlist-modal .primary{width:100%;margin-top:25px;background:#baf56b;color:#30511d}.close{position:absolute;top:15px;right:20px;border:0;background:none;font-size:25px;color:#9ba88c;cursor:pointer}button:disabled{opacity:.4;cursor:default}button:focus-visible,input:focus-visible,summary:focus-visible{outline:3px solid #498bed;outline-offset:3px}@media(max-width:800px){.playlist-heading{align-items:flex-start;flex-direction:column}.playlist-heading h1{font-size:27px}.playlist-layout{grid-template-columns:1fr}.playlist-tabs{flex-direction:row;overflow:auto}.playlist-tabs>button{min-width:150px}.playlist-title{padding:20px}.playlist-title h2{font-size:20px}.playlist-lesson{flex-wrap:wrap;padding:18px 15px;gap:12px}.lesson-open{min-width:140px}.row-actions{margin-left:auto}.playlist-modal{padding:30px 25px}}
